  });

  it("stays stale when the echo does not read back what was written", async () => {
    const routes = scenario({
      ancestor: [{ path: "shared.txt", sha: A }],
      base: [{ path: "shared.txt", sha: A }],
      head: [{ path: "shared.txt", sha: B2 }],
    });
    routes[`${COMMITS_PATH}/${DERIVED}`] = () => json(commit(DERIVED, MERGED_TREE, [HEAD, BASE]));
    const { impl } = fakeFetch(routes);
    const result = await resolveOrDeriveCandidate(githubHttp("token", impl), REPO, 42);
    expect(result).toEqual({ status: "blocked", reason: "CANDIDATE_STALE" });
  });

  it("stays stale when any read is refused", async () => {
    const routes = scenario({
      ancestor: [{ path: "shared.txt", sha: A }],
      base: [{ path: "shared.txt", sha: A }],
      head: [{ path: "shared.txt", sha: B2 }],
    });
    routes[COMPARE_PATH] = () => new Response("boom", { status: 502 });
    const { impl } = fakeFetch(routes);
    const result = await resolveOrDeriveCandidate(githubHttp("token", impl), REPO, 42);
    expect(result).toEqual({ status: "blocked", reason: "CANDIDATE_STALE" });
  });

  it("re-checks the pull request itself, because the first read is stale by definition here", async () => {
    // The synthetic-ref read found the stale verdict, but by the time
    // derivation asks, the pull request has been closed. Derivation must not
    // pin a candidate for a pull request that cannot merge.
    const routes = scenario({
      ancestor: [{ path: "shared.txt", sha: A }],
      base: [{ path: "shared.txt", sha: A }],
      head: [{ path: "shared.txt", sha: B2 }],
      pull: { state: "closed" },
    });
    // resolveCandidate also sees the close and refuses before derivation; run
    // the table through the stale path by closing only on the second read.
    let reads = 0;
    const secondRead = routes[PULL_PATH]!;
    routes[PULL_PATH] = (init) => {
      reads += 1;
      return reads === 1
        ? json({
            number: 42,
            state: "open",
            draft: false,
            mergeable: true,
            merge_commit_sha: STALE_CANDIDATE,
            base: { ref: "main", sha: BASE, repo: { id: 1315419165 } },
            head: { sha: HEAD, repo: { id: 1315419165 } },
          })
        : secondRead(init);
    };
    const { impl, calls } = fakeFetch(routes);
    const result = await resolveOrDeriveCandidate(githubHttp("token", impl), REPO, 42);
    expect(result).toEqual({ status: "blocked", reason: "CANDIDATE_STALE" });
    expect(calls.every((c) => c.method === "GET")).toBe(true);
  });

  it("does not derive when the pin is fresh", async () => {
    const routes = scenario({
      ancestor: [{ path: "shared.txt", sha: A }],
      base: [{ path: "shared.txt", sha: A }],
      head: [{ path: "shared.txt", sha: B2 }],
    });
    // The synthetic ref sits on the current base: resolution pins as-is.
    routes[`${COMMITS_PATH}/${STALE_CANDIDATE}`] = () => json(commit(STALE_CANDIDATE, "9".repeat(40), [BASE, HEAD]));
    routes[COMPARE_PATH] = () => {
