  1	import type { GitSubject } from "@thwip/queue-protocol";
  2	
  3	/**
  4	 * Candidate preparation.
  5	 *
  6	 * GitHub's `refs/pull/N/merge` is mutable and read-only, so the value is not the
  7	 * ref but the objects it pointed at: the candidate commit, its parents, and its
  8	 * tree. Everything downstream binds those, and this module is where they are
  9	 * pinned.
 10	 *
 11	 * What the landed commit is re-checked against lives in the transition record's
 12	 * own parse (`@thwip/queue-protocol`, `checkMergeConsistency`), which runs on
 13	 * every record the queue signs and on every record a reader verifies.
 14	 *
 15	 * The provider calls live behind a port. What is here is the reasoning, so it can
 16	 * be tested without GitHub.
 17	 */
 18	
 19	export interface PullRequestFacts {
 20	  readonly repositoryId: string;
 21	  readonly baseRef: string;
 22	  readonly baseSha: string;
 23	  readonly pullRequestNumber: number;
 24	  readonly headRepositoryId: string;
 25	  readonly headSha: string;
 26	  readonly state: "open" | "closed";
 27	  readonly draft: boolean;
 28	  /** Null while GitHub is still computing it (§16.1 step 2). */
 29	  readonly mergeable: boolean | null;
 30	  readonly mergeCommitSha: string | null;
 31	  readonly objectFormat: "sha1" | "sha256";
 32	}
 33	
 34	export interface CommitFacts {
 35	  readonly sha: string;
 36	  readonly treeOid: string;
 37	  readonly parentShas: readonly string[];
 38	}
 39	
 40	export type CandidateResult =
 41	  | { readonly status: "pinned"; readonly subject: GitSubject }
 42	  | { readonly status: "pending"; readonly reason: "MERGEABILITY_UNKNOWN" }
 43	  | { readonly status: "blocked"; readonly reason: CandidateBlockReason };
 44	
 45	export type CandidateBlockReason =
 46	  | "PR_CLOSED"
 47	  | "PR_DRAFT"
 48	  | "BASE_NOT_MANAGED"
 49	  | "MERGE_CONFLICT"
 50	  | "CANDIDATE_MISSING"
 51	  | "CANDIDATE_PARENTS_UNEXPECTED"
 52	  | "CANDIDATE_STALE";
 53	
 54	/** Every state candidate resolution can be in when it hands out no candidate. */
 55	export type CandidateStateReason = CandidateBlockReason | "MERGEABILITY_UNKNOWN";
 56	
 57	/**
 58	 * What the control plane hands its routes: the four objects a turn binds, or
 59	 * the state that stopped them being read.
 60	 *
 61	 * The reason travels because the routes act on these differently. A conflict
 62	 * ends the turn and frees the lane; mergeability GitHub has not finished
 63	 * computing keeps both. Collapsing them to null made every one of the eight
 64	 * read, to the operator, as GitHub being unreachable.
 65	 */
 66	export type IntegratedCandidate =
 67	  | {
 68	      readonly status: "pinned";
 69	      readonly baseSha: string;
 70	      readonly headSha: string;
 71	      readonly candidateSha: string;
 72	      readonly candidateTreeOid: string;
 73	    }
 74	  | { readonly status: "pending" | "blocked"; readonly reason: CandidateStateReason };
 75	
 76	/** The four objects a turn binds, or the state that stopped them being read. */
 77	export function integratedCandidateFrom(result: CandidateResult): IntegratedCandidate {
 78	  if (result.status !== "pinned") return { status: result.status, reason: result.reason };
 79	  return {
 80	    status: "pinned",
 81	    baseSha: result.subject.baseSha,
 82	    headSha: result.subject.headSha,
 83	    candidateSha: result.subject.candidateSha,
 84	    candidateTreeOid: result.subject.candidateTreeOid,
 85	  };
 86	}
 87	
 88	/**
 89	 * Turn live pull request facts and the candidate commit into a pinned subject,
 90	 * or say precisely why not.
 91	 *
 92	 * The parent checks are the load-bearing part: a candidate whose first parent is
 93	 * not the current base was simulated against a different branch tip, and a
 94	 * candidate whose second parent is not the current head tests different code.
 95	 */
 96	export function pinCandidate(input: {
 97	  readonly pr: PullRequestFacts;
 98	  readonly candidate: CommitFacts | null;
 99	  readonly expectedBaseRef: string;
100	}): CandidateResult {
101	  const { pr } = input;
102	  if (pr.state !== "open") return { status: "blocked", reason: "PR_CLOSED" };
103	  if (pr.draft) return { status: "blocked", reason: "PR_DRAFT" };
104	  if (pr.baseRef !== input.expectedBaseRef) return { status: "blocked", reason: "BASE_NOT_MANAGED" };
105	  if (pr.mergeable === null) return { status: "pending", reason: "MERGEABILITY_UNKNOWN" };
106	  if (!pr.mergeable) return { status: "blocked", reason: "MERGE_CONFLICT" };
107	  if (pr.mergeCommitSha === null || input.candidate === null) {
108	    return { status: "blocked", reason: "CANDIDATE_MISSING" };
109	  }
110	  if (input.candidate.sha !== pr.mergeCommitSha) return { status: "blocked", reason: "CANDIDATE_STALE" };
111	
112	  const parents = input.candidate.parentShas;
113	  if (parents.length !== 2) return { status: "blocked", reason: "CANDIDATE_PARENTS_UNEXPECTED" };
114	  // GitHub may keep the synthetic merge ref on the previous base after another
115	  // queued pull request lands. That is stale, not malformed: a fresh turn must
116	  // give GitHub another chance to rebuild it without changing the PR head.
117	  if (parents[1] !== pr.headSha) {
118	    return { status: "blocked", reason: "CANDIDATE_PARENTS_UNEXPECTED" };
119	  }
120	  if (parents[0] !== pr.baseSha) return { status: "blocked", reason: "CANDIDATE_STALE" };
121	
122	  return {
123	    status: "pinned",
124	    subject: {
125	      objectFormat: pr.objectFormat,
126	      repositoryId: pr.repositoryId,
127	      baseRef: pr.baseRef as `refs/heads/${string}`,
128	      baseSha: pr.baseSha,
129	      headRepositoryId: pr.headRepositoryId,
130	      headSha: pr.headSha,
131	      candidateSha: input.candidate.sha,
132	      candidateTreeOid: input.candidate.treeOid,
133	      candidateParentOids: [parents[0], parents[1]],
134	    },
135	  };
136	}

