 24	    "x-github-api-version": "2022-11-28",
 25	    ...(extra ?? {}),
 26	  });
 27	
 28	  return {
 29	    async json<T>(path: string, init?: RequestInit): Promise<T> {
 30	      const res = await fetchImpl(`${API}${path}`, { ...init, headers: headers(init?.headers) });
 31	      if (!res.ok) throw new GithubApiError(path, res.status, await res.text());
 32	      return (await res.json()) as T;
 33	    },
 34	  };
 35	}
 36	
 37	export interface RepoRef {
 38	  readonly owner: string;
 39	  readonly repo: string;
 40	  readonly repositoryId: string;
 41	  readonly baseRef: string;
 42	}
 43	
 44	interface PullResponse {
 45	  number: number;
 46	  state: string;
 47	  draft?: boolean;
 48	  mergeable: boolean | null;
 49	  merge_commit_sha: string | null;
 50	  base: { ref: string; sha: string; repo: { id: number; node_id?: string } };
 51	  head: { sha: string; repo: { id: number } | null };
 52	}
 53	
 54	interface CommitResponse {
 55	  sha: string;
 56	  tree: { sha: string };
 57	  parents: Array<{ sha: string }>;
 58	}
 59	
 60	/**
 61	 * Candidate resolution. GitHub computes mergeability
 62	 * asynchronously, so a null answer is polled for a short bound and then given up
 63	 * on rather than waited out — an entry that is not ready yet keeps its place and
 64	 * will be offered another turn.
 65	 */
 66	export async function resolveCandidate(
 67	  http: GitHubHttp,
 68	  repo: RepoRef,
 69	  pullRequestNumber: number,
 70	  options: { attempts?: number; sleep?: (ms: number) => Promise<void> } = {},
 71	): Promise<ReturnType<typeof pinCandidate>> {
 72	  const attempts = options.attempts ?? 4;
 73	  const sleep = options.sleep ?? ((ms: number) => new Promise((r) => setTimeout(r, ms)));
 74	
 75	  let pull: PullResponse | null = null;
 76	  for (let i = 0; i < attempts; i += 1) {
 77	    pull = await http.json<PullResponse>(`/repos/${repo.owner}/${repo.repo}/pulls/${pullRequestNumber}`);
 78	    if (pull.mergeable !== null || pull.state !== "open") break;
 79	    if (i < attempts - 1) await sleep(500 * (i + 1));
 80	  }
 81	  if (pull === null) return { status: "blocked", reason: "CANDIDATE_MISSING" };
 82	
 83	  // Where the branch actually points, read from the ref rather than taken from
 84	  // the pull request.
 85	  //
 86	  // GitHub caches `base.sha` on the pull request and updates it late, and it
 87	  // caches the test merge alongside it. When both lag the same push they agree
 88	  // with each other, so the parent check below passed and the queue pinned a
 89	  // base that was already gone. It signed an intent naming that base, the merge
 90	  // write was refused 422, the attempt resolved, the lane offered the same turn
 91	  // again, and the same stale pair came back. Pull request 206 sat in that loop
 92	  // until somebody force-pushed it out.
 93	  //
 94	  // Reading the ref costs one call and makes the disagreement visible: the
 95	  // candidate's first parent no longer matches, so the turn is refused as stale
 96	  // and retried once GitHub has recomputed the merge.
 97	  const baseSha = (
 98	    await http.json<{ object: { sha: string } }>(
 99	      `/repos/${repo.owner}/${repo.repo}/git/ref/heads/${pull.base.ref}`,
100	    )
101	  ).object.sha;
102	
103	  const facts: PullRequestFacts = {
104	    repositoryId: String(pull.base.repo.id),
105	    baseRef: `refs/heads/${pull.base.ref}`,
106	    baseSha,
107	    pullRequestNumber: pull.number,
108	    headRepositoryId: String(pull.head.repo?.id ?? pull.base.repo.id),
109	    headSha: pull.head.sha,
110	    state: pull.state === "open" ? "open" : "closed",
111	    draft: pull.draft === true,
112	    mergeable: pull.mergeable,
113	    mergeCommitSha: pull.merge_commit_sha,
114	    objectFormat: baseSha.length === 64 ? "sha256" : "sha1",
115	  };
116	
117	  let candidate: CommitFacts | null = null;
118	  if (facts.mergeCommitSha !== null) {
119	    const commit = await http.json<CommitResponse>(
120	      `/repos/${repo.owner}/${repo.repo}/git/commits/${facts.mergeCommitSha}`,
121	    );
122	    candidate = {
123	      sha: commit.sha,
124	      treeOid: commit.tree.sha,
125	      parentShas: commit.parents.map((p) => p.sha),
126	    };
127	  }
128	
129	  return pinCandidate({ pr: facts, candidate, expectedBaseRef: repo.baseRef });
130	}
131	
132	/**
133	 * Candidate reads live here; the single merge implementation does not.
134	 *
135	 * The App-owned writer is `merge-write.ts`. It composes the verified tree on
136	 * the pinned base and updates the branch ref without force. Keeping that write
137	 * out of this general read boundary makes duplicate merge paths harder to add.
138	 */
139	
140	/** One check run on a head, as far as a required-status-check rule cares. */
141	export interface CheckRunFact {
142	  readonly name: string;
143	  readonly status: string;
144	  readonly conclusion: string | null;
145	}
146	
147	/** What the branch requires and what the head says about it. */
148	export interface RequiredCheckState {
149	  /** Contexts a `required_status_checks` rule names for this branch. */
150	  readonly required: readonly string[];
151	  /** The latest run per name on the head. */
152	  readonly runs: readonly CheckRunFact[];
153	}
154	
155	/** Conclusions GitHub counts as satisfying a required status check. */
156	const SATISFYING = new Set(["success", "neutral", "skipped"]);
157	
158	/**
159	 * Required checks this head will certainly be refused on.
160	 *
161	 * The queue used to find this out from GitHub's rejection. It would offer a turn,
162	 * authorize the merge, and the PUT came back 405 because a required check was
163	 * missing — and the attempt then held the lane while everything behind it
164	 * stopped. Both facts are readable before the ask: the branch rules name the
165	 * contexts, and the head carries the runs.
166	 *
167	 * Only the certain cases. A context with no run at all cannot pass, and one that
168	 * concluded badly goes on refusing until something re-runs it. A run still in
169	 * progress is left alone: it may yet pass, and refusing on it would turn every
170	 * ordinary race into a refusal.
171	 */
172	export function unsatisfiedRequiredChecks(
173	  state: RequiredCheckState,
174	): Array<{ context: string; state: "absent" | "failed" }> {
175	  const unsatisfied: Array<{ context: string; state: "absent" | "failed" }> = [];
176	  for (const context of state.required) {
177	    const matching = state.runs.filter((run) => run.name === context);
178	    if (matching.length === 0) {
179	      unsatisfied.push({ context, state: "absent" });
180	      continue;
181	    }
182	    if (matching.some((run) => run.status === "completed" && SATISFYING.has(run.conclusion ?? ""))) continue;
183	    if (matching.some((run) => run.status !== "completed")) continue;
184	    unsatisfied.push({ context, state: "failed" });
185	  }
186	  return unsatisfied;
187	}

