500	 *
501	 * The local-run half of this is a refusal, not a step. Under `fresh` and
502	 * `audited` the merge rests on a run that happened on somebody's machine, and
503	 * the only account of it is a receipt this queue accepted. So the receipt is
504	 * checked against the queue document itself — the tree the attempt pinned, the
505	 * device that claimed the offer, the assignment that device was issued — and a
506	 * disagreement stops the walk here, where a route cannot go around it.
507	 */
508	export function walkToMergeReady(
509	  commands: QueueCommands,
510	  store: QueueStateStore,
511	  input: WalkInput,
512	): { operationId: string | null; snapshot: QueueSnapshot; refusal?: WalkRefusal } {
513	  const ok = (r: { status: string }) => r.status === "applied" || r.status === "duplicate";
514	  const done = (operationId: string | null, refusal?: WalkRefusal) => ({
515	    operationId,
516	    snapshot: buildSnapshot(store),
517	    ...(refusal === undefined ? {} : { refusal }),
518	  });
519	
520	  const attempt = store.state().attempts.get(input.attemptId);
521	  if (attempt === undefined) return done(null, "NO_SUCH_ATTEMPT");
522	  const localRun = input.evidence.localRun;
523	
524	  if (localRun !== null) {
525	    // Everything about this receipt has to be about this attempt. The digests
526	    // were written by the claim and receipt routes into the queue document as
527	    // well as into storage, so a receipt that satisfied the gate but names an
528	    // assignment or a tree the queue never recorded is two accounts of one turn
529	    // disagreeing, and neither may be merged on.
530	    if (attempt.assignmentDigest !== localRun.assignmentDigest) {
531	      return done(null, "INTEGRATION_ASSIGNMENT_MISMATCH");
532	    }
533	    if (attempt.receiptDigest !== localRun.receiptDigest) {
534	      return done(null, "INTEGRATION_RECEIPT_MISMATCH");
535	    }
536	    if (attempt.candidateTree !== localRun.candidateTreeOid || input.candidateTree !== localRun.candidateTreeOid) {
537	      return done(null, "INTEGRATION_RECEIPT_TREE_MISMATCH");
538	    }
539	    // The offer was claimed by a device, and the receipt has to come from that
540	    // device. `acceptIntegrationReceipt` checks the receipt against the
541	    // assignment; this checks it against who the queue let take the turn.
542	    if (attempt.deviceId !== localRun.deviceKeyId) {
543	      return done(null, "INTEGRATION_RECEIPT_DEVICE_MISMATCH");
544	    }
545	  }
546	
547	  // Pinned already where a device was dispatched: the candidate is what the
548	  // assignment was built over, and the reducer holds it immutable. Re-issuing
549	  // the command would be rejected and stop a merge that is in order.
550	  if (attempt.candidateSha === null) {
551	    const prepared = commands.candidatePrepared({
552	      idempotencyKey: `authorize:candidate:${input.attemptId}`,
553	      attemptId: input.attemptId,
554	      baseSha: input.baseSha,
555	      headSha: input.headSha,
556	      candidateSha: input.candidateSha,
557	      candidateTree: input.candidateTree,
558	      policyDigest: input.policyDigest,
559	      runner: input.runner as never,
560	    });
561	    if (!ok(prepared)) return done(null, "CANDIDATE_NOT_PINNED");
562	  } else if (attempt.candidateTree !== input.candidateTree || attempt.candidateSha !== input.candidateSha) {
563	    // The caller is about to merge something other than what this attempt was
564	    // run against.
565	    return done(null, "CANDIDATE_CHANGED");
566	  }
567	
568	  // A device's receipt was submitted when it arrived. Only the reuse walk
569	  // submits one here, and only the reuse walk has one to submit.
570	  if (attempt.receiptDigest === null) {
571	    commands.submitReceipt({
572	      idempotencyKey: `authorize:receipt:${input.attemptId}`,
573	      attemptId: input.attemptId,
574	      receiptDigest: input.receiptDigest,
575	    });
576	  }
577	  const started = commands.startVerification({
578	    idempotencyKey: `authorize:verify:${input.attemptId}`,
579	    attemptId: input.attemptId,
580	  });
581	  const nonce = "nonce" in started ? (started as { nonce: string }).nonce : undefined;
582	  if (nonce === undefined) return done(null, "VERIFICATION_NOT_STARTED");
583	
584	  commands.completeVerification({
585	    idempotencyKey: `authorize:verdict:${input.attemptId}`,
586	    attemptId: input.attemptId,
587	    nonce,
588	    accepted: true,
589	    resultDigest: input.verifierResultDigest,
590	  });
591	  const intent = commands.createMergeIntent({
592	    idempotencyKey: `authorize:intent:${input.attemptId}`,
593	    attemptId: input.attemptId,
594	    intentDigest: input.intentDigest,
