509	  commands: QueueCommands,
510	  store: QueueStateStore,
511	  input: WalkInput,
512	): { operationId: string | null; snapshot: QueueSnapshot; refusal?: WalkRefusal } {
513	  const ok = (r: { status: string }) => r.status === "applied" || r.status === "duplicate";
