  1	import { canonicalRecordBytes, recordDigest } from "@thwip/queue-protocol";
  2	import type { CandidateSuite, CandidateVerdict } from "./store.js";
  3	
  4	/**
  5	 * Whether a verifier's verdict may back a merge.
  6	 *
  7	 * Until this existed the merge-preparation path walked an attempt to merge-ready
  8	 * with a constant standing in for the verifier's result. The queue then recorded
  9	 * a verified transition, and what it had actually verified was the proof on the
 10	 * pull request head — work done before the branch was integrated. Nothing had run
 11	 * the suites against the merge commit.
 12	 *
 13	 * The decision is separated from both the HTTP layer and storage so it can be
 14	 * tested exhaustively, and so every refusal has a name a caller can act on.
 15	 */
 16	
 17	/**
 18	 * Which security profiles are a claim about the integrated candidate.
 19	 *
 20	 * `fast` states that the evidence is the proof already on the head — work done
 21	 * before the branch was integrated — and merging on it is what that policy asks
 22	 * for, not a shortcut. Every other profile claims something was run against the
 23	 * integration itself, and that claim needs a verifier result to be true.
 24	 */
 25	export function requiresIntegratedRun(securityProfile: string): boolean {
 26	  return securityProfile !== "fast";
 27	}
 28	
 29	/**
 30	 * Which of those profiles want that run performed by the pinned verifier in
 31	 * GitHub Actions.
 32	 *
 33	 * `fresh` runs the integration on the developer's own machine and has no
 34	 * fallback to Actions, so asking a pinned verifier for a verdict
 35	 * would refuse every `fresh` merge for want of a workflow the profile does not
 36	 * use. `audited` is `fresh` plus that second execution, so it wants both, and
 37	 * `remote` is the second execution alone.
 38	 */
 39	export function requiresRemoteVerification(securityProfile: string): boolean {
 40	  return requiresIntegratedRun(securityProfile) && securityProfile !== "fresh";
 41	}
 42	
 43	export type CandidateRefusal =
 44	  | "CANDIDATE_NOT_VERIFIED"
 45	  | "CANDIDATE_TREE_MISMATCH"
 46	  | "CANDIDATE_BASE_MOVED"
 47	  | "CANDIDATE_REJECTED"
 48	  | "CANDIDATE_DIGEST_MISMATCH"
 49	  | "CANDIDATE_POLICY_MISMATCH"
 50	  | "CANDIDATE_SUITE_NOT_PASSED"
 51	  | "CANDIDATE_SUITES_INCOMPLETE"
 52	  | "CANDIDATE_SUITE_DUPLICATE"
 53	  | "CANDIDATE_VERIFIER_NOT_PINNED";
 54	
 55	export interface CandidateExpectation {
 56	  readonly candidateTreeOid: string;
 57	  readonly candidateSha: string;
 58	  readonly baseSha: string;
 59	  /** The suites the active policy requires. A verdict missing one proves less. */
 60	  readonly requiredSuites: readonly string[];
 61	  readonly policyDigest: string;
 62	  /** The verifier workflow the repository pinned. */
 63	  readonly workflowRef: string;
 64	  /** The exact revision, or null for any revision of that path on the default branch. */
 65	  readonly workflowSha: string | null;
 66	}
 67	
 68	export type CandidateDecision =
 69	  | { readonly ok: true; readonly resultDigest: string }
 70	  | { readonly ok: false; readonly code: CandidateRefusal; readonly detail: string };
 71	
 72	/**
 73	 * The digest of a verdict, computed from its content.
 74	 *
 75	 * The merge gate recomputes this instead of trusting the stored field, so a
 76	 * verdict whose suites or outcome were edited after the fact no longer matches
 77	 * the digest that goes into the transition chain.
 78	 */
 79	function verdictRecord(input: {
 80	  readonly candidateTreeOid: string;
 81	  readonly candidateSha: string;
 82	  readonly baseSha: string;
 83	  readonly policyDigest: string;
 84	  readonly accepted: boolean;
 85	  readonly suites: readonly CandidateSuite[];
 86	  readonly reasonCodes: readonly string[];
 87	  readonly workflowRef: string;
 88	  readonly workflowSha: string;
 89	  readonly runId: string;
 90	}) {
 91	  return {
 92	    predicate: "urn:thwip:queue:candidate-verdict:v1",
 93	    candidateTreeOid: input.candidateTreeOid,
 94	    candidateSha: input.candidateSha,
 95	    baseSha: input.baseSha,
 96	    policyDigest: input.policyDigest,
 97	    accepted: input.accepted,
 98	    // Sorted, so two runs that report the same suites in a different order agree.
 99	    suites: [...input.suites]
100	      .map((s) => ({ name: s.name, outcome: s.outcome, durationMs: s.durationMs }))
101	      .sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0)),
102	    reasonCodes: [...input.reasonCodes].sort(),
103	    workflowRef: input.workflowRef,
104	    workflowSha: input.workflowSha,
105	    runId: input.runId,
106	  };
107	}
108	
109	/**
110	 * The exact bytes the digest covers.
111	 *
112	 * Stored evidence is named by the hash of its own content, so the bytes written
113	 * to the store and the bytes hashed here have to be the same bytes. Deriving both
114	 * from one record is what keeps them that way.
115	 */
116	export function candidateResultBytes(input: Parameters<typeof verdictRecord>[0]): Uint8Array {
117	  return canonicalRecordBytes(verdictRecord(input));
118	}
119	
120	export async function candidateResultDigest(input: {
121	  readonly candidateTreeOid: string;
122	  readonly candidateSha: string;
123	  readonly baseSha: string;
124	  readonly policyDigest: string;
125	  readonly accepted: boolean;
126	  readonly suites: readonly CandidateSuite[];
127	  readonly reasonCodes: readonly string[];
128	  readonly workflowRef: string;
129	  readonly workflowSha: string;
130	  readonly runId: string;
131	}): Promise<string> {
132	  return recordDigest(verdictRecord(input));
133	}
134	
135	export async function decideCandidate(
136	  verdict: CandidateVerdict | null,
137	  expected: CandidateExpectation,
138	): Promise<CandidateDecision> {
139	  if (verdict === null) {
140	    return {
141	      ok: false,
142	      code: "CANDIDATE_NOT_VERIFIED",
143	      detail: `no verifier result for candidate tree ${expected.candidateTreeOid}`,
144	    };
145	  }
146	
147	  // The tree is the identity of the integration. Everything else is a
148	  // cross-check, but a verdict about another tree is about other code.
149	  if (verdict.candidateTreeOid !== expected.candidateTreeOid) {
150	    return { ok: false, code: "CANDIDATE_TREE_MISMATCH", detail: "the verdict names another tree" };
151	  }
152	  // The candidate commit's own hash is not checked, and must not be.
153	  //
154	  // The tree is the code and the base is what it merges onto; together they fix
155	  // exactly what the suites ran against. A commit hash also folds in the message,
156	  // the author and the timestamp, so GitHub recreating the merge commit for an
157	  // unchanged pull request produces a different hash for identical code. It does
158	  // that whenever the base branch moves.
159	  //
160	  // Gating on it deadlocked a pull request tonight. A verdict is immutable and
161	  // keyed by tree, so once the hash had moved on there was no hash that could
162	  // ever match and no second verdict that could replace it: the queue refused the
163	  // merge, released the lane, offered the same turn back, and refused again. The
164	  // hash is still recorded on the verdict, where it belongs, as provenance.
165	
166	  // The same tree can be reached from a different base after a fast-forward. The
167	  // suites passing there does not establish they pass here.
168	  if (verdict.baseSha !== expected.baseSha) {
169	    return {
170	      ok: false,
171	      code: "CANDIDATE_BASE_MOVED",
172	      detail: `verified against base ${verdict.baseSha}, merging onto ${expected.baseSha}`,
173	    };
174	  }
175	
176	  if (
177	    verdict.workflowRef !== expected.workflowRef ||
178	    (expected.workflowSha !== null && verdict.workflowSha !== expected.workflowSha)
179	  ) {
180	    return {
181	      ok: false,
182	      code: "CANDIDATE_VERIFIER_NOT_PINNED",
183	      detail: "the verdict came from a workflow this repository has not pinned",
184	    };
185	  }
186	
187	  if (verdict.policyDigest !== expected.policyDigest) {
188	    return {
189	      ok: false,
190	      code: "CANDIDATE_POLICY_MISMATCH",
191	      detail: "the policy changed after the candidate was verified",
192	    };
193	  }
194	
195	  const recomputed = await candidateResultDigest(verdict);
196	  if (recomputed !== verdict.resultDigest) {
197	    return {
198	      ok: false,
199	      code: "CANDIDATE_DIGEST_MISMATCH",
200	      detail: "the stored verdict does not match its own digest",
201	    };
202	  }
203	
204	  if (!verdict.accepted) {
205	    return {
206	      ok: false,
207	      code: "CANDIDATE_REJECTED",
208	      detail: verdict.reasonCodes.length > 0 ? verdict.reasonCodes.join(", ") : "the verifier refused",
209	    };
210	  }
211	
212	  // One name, one result. A workflow that re-runs a job and reports both lines
213	  // sends `test: failed` followed by `test: passed`; indexed by name the second
214	  // line erased the first, and the digest still matched because it covers the
215	  // whole list. The proof verifier refuses this shape outright (SUITE_DUPLICATE)
216	  // and the merge gate now refuses it the same way, rather than picking which of
217	  // two disagreeing results to believe.
218	  const duplicates = [
219	    ...new Set(verdict.suites.filter((s, i) => verdict.suites.findIndex((o) => o.name === s.name) !== i).map((s) => s.name)),
220	  ];

