1266	      return c.json({ error: "ALREADY_CLAIMED", detail: `the turn is ${entry.state}` }, 409);
1267	    }
1268	    if (!(await isPrincipalConnected(db, repositoryId, who.principalId, new Date().toISOString()))) {
1269	      return c.json(
1270	        { error: "RUNNER_NOT_CONNECTED", detail: "heartbeat first, so the queue knows this machine is here" },
1271	        409,
1272	      );
1273	    }
1274	
1275	    if (deps.integratedCandidate === undefined) {
1276	      return c.json({ error: "CANDIDATE_UNAVAILABLE", detail: "this deployment cannot resolve a candidate" }, 503);
1277	    }
1278	    const candidate = await deps.integratedCandidate(c.env, repositoryId, baseRef, entry.pullRequestNumber);
1279	    if (candidate === null || candidate.status !== "pinned") {
1280	      // GitHub computes mergeability asynchronously, and a pull request that
1281	      // cannot be integrated has no candidate at all. Neither is a reason to
1282	      // hand a device a tree to run, and the device is told which it is.
1283	      return c.json(
1284	        {
1285	          error: "CANDIDATE_UNAVAILABLE",
1286	          detail:
1287	            candidate === null
1288	              ? "GitHub would not say what this pull request integrates to"
1289	              : nextAction(candidate.reason),
1290	        },
1291	        409,
1292	      );
1293	    }
1294	
1295	    // The proof on the head, which the assignment binds. No digest means the
1296	    // required check has nothing to have accepted, so there is no turn to run.
1297	    const head = await deps.commitFacts(c.env, repositoryId, candidate.headSha);
1298	    const workReceiptDigest = head?.message === undefined ? null : await workReceiptDigestFrom(head.message);
1299	    if (workReceiptDigest === null) {
1300	      return c.json(
1301	        { error: "WORK_RECEIPT_UNREADABLE", detail: "the head commit carries no readable thwip proof" },
1302	        409,
1303	      );
1304	    }
1305	
1306	    // GitHub's own id for the account that owns the repository, which is what an
1307	    // assignment names. The organization id storage uses is this deployment's
1308	    // key for a tenant and means nothing to a device checking the record.
1309	    const owner = await db
1310	      .prepare(
1311	        `SELECT o.github_org_id AS ownerId
1312	           FROM projects p JOIN organizations o ON o.id = p.organization_id
1313	          WHERE p.github_repository_id = ?`,
1314	      )
1315	      .bind(repositoryId)
1316	      .first<{ ownerId: string }>();
1317	    if (owner === null || !/^[0-9]{1,32}$/.test(owner.ownerId)) {
1318	      return c.json({ error: "OWNER_UNKNOWN", detail: "this repository's owner has no GitHub id recorded" }, 409);
1319	    }
1320	
1321	    // What the scheduler decided when it offered this turn. The device checks
1322	    // the assignment against the protocol, and this field is its handle on why
1323	    // the turn is its own; binding a digest naming no record told it nothing and
1324	    // passed anyway, because the check only reads the field's shape.
1325	    const queueDecisionDigest = snapshot.activeDecisionDigest;

