  1	import type { D1Like } from "./projection.js";
  2	import type { SubmittedReceiptSuite } from "./integration-receipt.js";
  3	
  4	/**
  5	 * The assignments this queue handed to a device, and the receipts it accepted
  6	 * back (migration 0021).
  7	 *
  8	 * Under `fresh` and `audited` the suites run on the developer's machine, so the
  9	 * merge gate has no evidence to weigh unless the dispatch and the answer are
 10	 * durable. Everything the gate compares lives in one row: the tree the device
 11	 * was told to run, the device that was told to run it, and the receipt that
 12	 * came back. A gate reading two tables could find one half and act on it.
 13	 *
 14	 * Neither write trusts the caller to have checked first. Issuing a second
 15	 * assignment for an attempt loses to the unique index rather than replacing the
 16	 * first, and accepting a receipt matches on `receipt_digest IS NULL`, so a
 17	 * second receipt for the same assignment changes nothing.
 18	 */
 19	
 20	export interface IssuedAssignmentRecord {
 21	  readonly assignmentId: string;
 22	  readonly repositoryId: string;
 23	  readonly baseRef: string;
 24	  readonly attemptId: string;
 25	  readonly assignmentDigest: string;
 26	  readonly candidateSha: string;
 27	  readonly candidateTreeOid: string;
 28	  readonly principalId: string;
 29	  readonly deviceKeyId: string;
 30	  readonly requiredSuites: readonly string[];
 31	  readonly executionSeconds: number;
 32	  readonly issuedAt: string;
 33	}
 34	
 35	export interface AcceptedReceiptRecord {
 36	  readonly assignmentId: string;
 37	  readonly attemptId: string;
 38	  readonly receiptDigest: string;
 39	  readonly candidateTreeOid: string;
 40	  readonly deviceKeyId: string;
 41	  readonly assignmentDigest: string;
 42	  readonly suites: readonly SubmittedReceiptSuite[];
 43	  readonly acceptedAt: string;
 44	}
 45	
 46	export interface StoredAssignment extends IssuedAssignmentRecord {
 47	  /** Null until a receipt has been accepted for it. */
 48	  readonly receipt: AcceptedReceiptRecord | null;
 49	}
 50	
 51	interface AssignmentRow {
 52	  assignment_id: string;
 53	  github_repository_id: string;
 54	  base_ref: string;
 55	  attempt_id: string;
 56	  assignment_digest: string;
 57	  candidate_sha: string;
 58	  candidate_tree_oid: string;
 59	  principal_id: string;
 60	  device_key_id: string;
 61	  required_suites: string;
 62	  execution_seconds: number;
 63	  issued_at: string;
 64	  receipt_digest: string | null;
 65	  receipt_suites: string | null;
 66	  receipt_accepted_at: string | null;
 67	}
 68	
 69	const COLUMNS = `assignment_id, github_repository_id, base_ref, attempt_id, assignment_digest,
 70	                 candidate_sha, candidate_tree_oid, principal_id, device_key_id, required_suites,
 71	                 execution_seconds, issued_at, receipt_digest, receipt_suites, receipt_accepted_at`;
 72	
 73	function fromRow(row: AssignmentRow): StoredAssignment {
 74	  const receipt: AcceptedReceiptRecord | null =
 75	    row.receipt_digest === null || row.receipt_accepted_at === null
 76	      ? null
 77	      : {
 78	          assignmentId: row.assignment_id,
 79	          attemptId: row.attempt_id,
 80	          receiptDigest: row.receipt_digest,
 81	          candidateTreeOid: row.candidate_tree_oid,
 82	          deviceKeyId: row.device_key_id,
 83	          assignmentDigest: row.assignment_digest,
 84	          suites: JSON.parse(row.receipt_suites ?? "[]") as SubmittedReceiptSuite[],
 85	          acceptedAt: row.receipt_accepted_at,
 86	        };
 87	  return {
 88	    assignmentId: row.assignment_id,
 89	    repositoryId: row.github_repository_id,
 90	    baseRef: row.base_ref,
 91	    attemptId: row.attempt_id,
 92	    assignmentDigest: row.assignment_digest,
 93	    candidateSha: row.candidate_sha,
 94	    candidateTreeOid: row.candidate_tree_oid,
 95	    principalId: row.principal_id,
 96	    deviceKeyId: row.device_key_id,
 97	    requiredSuites: JSON.parse(row.required_suites) as string[],
 98	    executionSeconds: row.execution_seconds,
 99	    issuedAt: row.issued_at,
100	    receipt,
101	  };
102	}
103	
104	/**
105	 * Write down an assignment that has just been issued.
106	 *
107	 * `duplicate` means this attempt already had one, and the caller must use that
108	 * one rather than the one it just built: two devices racing the same offer both
109	 * reach here, and letting the second overwrite would leave the queue holding an
110	 * assignment for a device the reducer never let claim the offer.
111	 */
112	export async function recordIssuedAssignment(
113	  db: D1Like,
114	  record: IssuedAssignmentRecord,
115	): Promise<{ status: "applied" } | { status: "duplicate"; held: StoredAssignment }> {
116	  const held = await issuedAssignmentForAttempt(db, record.attemptId);
117	  if (held !== null) return { status: "duplicate", held };
118	
119	  try {
120	    await db
121	      .prepare(
122	        `INSERT INTO queue_assignments (
123	           assignment_id, github_repository_id, base_ref, attempt_id, assignment_digest,
124	           candidate_sha, candidate_tree_oid, principal_id, device_key_id, required_suites,
125	           execution_seconds, issued_at
126	         ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
127	      )
128	      .bind(
129	        record.assignmentId,
130	        record.repositoryId,
131	        record.baseRef,
132	        record.attemptId,
133	        record.assignmentDigest,
134	        record.candidateSha,
135	        record.candidateTreeOid,
136	        record.principalId,
137	        record.deviceKeyId,
138	        JSON.stringify([...record.requiredSuites]),
139	        record.executionSeconds,
140	        record.issuedAt,
141	      )
142	      .run();
143	    return { status: "applied" };
144	  } catch (error) {
145	    // The read above narrows the race, the unique index closes it. A loser
146	    // reports the winner rather than throwing, because losing a race is not
147	    // this caller's error.
148	    const winner = await issuedAssignmentForAttempt(db, record.attemptId);
149	    if (winner === null) throw error;
150	    return { status: "duplicate", held: winner };
151	  }
152	}
153	
154	export async function issuedAssignment(db: D1Like, assignmentId: string): Promise<StoredAssignment | null> {
155	  const row = await db
156	    .prepare(`SELECT ${COLUMNS} FROM queue_assignments WHERE assignment_id = ?`)
157	    .bind(assignmentId)
158	    .first<AssignmentRow>();
159	  return row === null ? null : fromRow(row);
160	}
161	
162	export async function issuedAssignmentForAttempt(db: D1Like, attemptId: string): Promise<StoredAssignment | null> {
163	  const row = await db
164	    .prepare(`SELECT ${COLUMNS} FROM queue_assignments WHERE attempt_id = ?`)
165	    .bind(attemptId)
166	    .first<AssignmentRow>();
167	  return row === null ? null : fromRow(row);
168	}
169	
170	/**
171	 * Record that a receipt was accepted for an assignment.
172	 *
173	 * `duplicate` means one was already accepted, and it stands. A later receipt
174	 * asks the queue to change what it will merge on, after the gate may already
175	 * have read the first, so it is refused rather than obeyed — the same rule the
176	 * reducer applies to a verdict that arrives too late.
177	 */
178	export async function recordAcceptedReceipt(
179	  db: D1Like,
180	  input: {
181	    readonly assignmentId: string;
182	    readonly receiptDigest: string;
183	    readonly suites: readonly SubmittedReceiptSuite[];
184	    readonly acceptedAt: string;
185	  },
186	): Promise<{ status: "applied" | "duplicate" | "unknown-assignment" }> {
187	  const existing = await issuedAssignment(db, input.assignmentId);
188	  if (existing === null) return { status: "unknown-assignment" };
189	  if (existing.receipt !== null) return { status: "duplicate" };
190	
191	  await db
192	    .prepare(
193	      `UPDATE queue_assignments
194	          SET receipt_digest = ?, receipt_suites = ?, receipt_accepted_at = ?
195	        WHERE assignment_id = ? AND receipt_digest IS NULL`,
196	    )
197	    .bind(input.receiptDigest, JSON.stringify([...input.suites]), input.acceptedAt, input.assignmentId)
198	    .run();
199	
200	  const after = await issuedAssignment(db, input.assignmentId);
201	  return { status: after?.receipt?.receiptDigest === input.receiptDigest ? "applied" : "duplicate" };
202	}
203	
204	/** The accepted receipt for an attempt, or null while there is none. */
205	export async function acceptedReceiptFor(db: D1Like, attemptId: string): Promise<AcceptedReceiptRecord | null> {
206	  const stored = await issuedAssignmentForAttempt(db, attemptId);
207	  return stored?.receipt ?? null;
208	}

