  1	/**
  2	 * Performing the merge the queue authorized, from the Worker.
  3	 *
  4	 * The App owns the write. Writing a commit object and moving a ref are both
  5	 * covered by `contents: write`; GitHub additionally requires `workflows: write`
  6	 * when the tree changes `.github/workflows`. `appOwnershipRuleset` names the
  7	 * App as the only actor that may update the queued branch, so the fast-forward
  8	 * guard is code this repository tests directly.
  9	 *
 10	 * The guard is one sentence. GitHub accepts a ref update without force only
 11	 * where the branch is an ancestor of the new commit, and the only branch that is
 12	 * an ancestor of a commit whose first parent is the pinned base is that base. So
 13	 * a base that moved makes GitHub refuse and the merge does not happen at all.
 14	 * Pull requests 114, 117, 119 and 121 each merged onto a base they were not
 15	 * verified against, through an API that takes an expected head and no expected
 16	 * base, and GitHub reported all four as successes.
 17	 *
 18	 * Nothing here decides anything about the merge. The base, the tree and the
 19	 * parents come from the queue document; this composes exactly those and moves
 20	 * the branch to the result, and the reducer refuses a confirmation whose first
 21	 * parent is not the pinned base as the second net.
 22	 */
 23	
 24	import { confirmMergeAbsence } from "./merge-absence.js";
 25	
 26	/**
 27	 * The one shape a branch move may take.
 28	 *
 29	 * `force` is typed to the literal `false` rather than to `boolean`, so a caller
 30	 * that wants to force cannot be written. `merge-write.test.ts` also reads the
 31	 * recorded request back at the runtime boundary.
 32	 */
 33	export interface RefUpdate {
 34	  readonly sha: string;
 35	  readonly force: false;
 36	}
 37	
 38	/**
 39	 * The JSON body of a branch move, built in one place.
 40	 *
 41	 * The type already makes a forcing caller unwriteable. This is the same rule at
 42	 * runtime, for the boundary where a `RefUpdate` arrives as parsed JSON and the
 43	 * type has stopped meaning anything: an update that says anything but
 44	 * `force: false` never reaches GitHub.
 45	 */
 46	export function refUpdateRequestBody(update: RefUpdate): string {
 47	  if (update.force !== false) {
 48	    throw new Error(
 49	      "a queue merge moves the branch without force; the update that does not force is what makes GitHub refuse a base that moved",
 50	    );
 51	  }
 52	  return JSON.stringify({ sha: update.sha, force: false });
 53	}
 54	
 55	export interface MergeWriteGithub {
 56	  /** Write the merge commit object. Writes nothing to any branch. */
 57	  createCommit(input: {
 58	    message: string;
 59	    tree: string;
 60	    parents: readonly string[];
 61	  }): Promise<{ ok: true; sha: string } | { ok: false; status: number; message: string }>;
 62	  /** Move a branch to a commit. The only call here that changes the repository. */
 63	  updateRef(
 64	    ref: string,
 65	    update: RefUpdate,
 66	  ): Promise<{ ok: true; sha: string } | { ok: false; status: number; message: string }>;
 67	  /** What the pull request says about itself, or null when it could not be read. */
 68	  readPull(): Promise<{ merged: boolean; mergeCommitSha: string | null } | null>;
 69	  /** Whether the base branch already contains the head, from git ancestry. */
 70	  baseContainsHead(): Promise<boolean | null>;
 71	  /**
 72	   * Whether GitHub reads the App's own required check on this head as
 73	   * concluded. Null where the check runs could not be read.
 74	   *
 75	   * Not optional. A caller that could leave it out would move the branch into
 76	   * the race this exists to close, and would do it silently.
 77	   */
 78	  requiredTurnCheckConcluded(): Promise<boolean | null>;
 79	}
 80	
 81	/** The commit the queue pinned. Every field comes from the queue document. */
 82	export interface MergeIntent {
 83	  readonly baseRef: string;
 84	  /** Which pull request, so a failed write can ask what became of it. */
 85	  readonly pullRequestNumber: number;
 86	  readonly baseSha: string;
 87	  readonly headSha: string;
 88	  readonly treeOid: string;
 89	  readonly parentShas: readonly string[];
 90	  readonly message: string;
 91	}
 92	
 93	export type MergeWriteOutcome =
 94	  /** `mergeSha` is null where git settled it and the branch was not read. */
 95	  | { readonly kind: "merged"; readonly mergeSha: string | null }
 96	  | { readonly kind: "base-moved"; readonly detail: string }
 97	  | { readonly kind: "not-merged"; readonly detail: string }
 98	  | { readonly kind: "refused"; readonly detail: string }
 99	  | { readonly kind: "unknown"; readonly detail: string };
100	
101	/** GitHub's wording for the refusal that means the base is no longer the base. */
102	const NOT_A_FAST_FORWARD = /not a fast forward/i;
103	
104	/**
105	 * GitHub's wording for a required check it has not finished reading.
106	 *
107	 * The Worker publishes `thwip / turn` green and moves the branch inside one
108	 * request, and GitHub's rule evaluation runs behind its own check-run write, so
109	 * the ref update is refused with 422 naming a check that just concluded.
110	 * Narrow on purpose. A required check that is genuinely unsatisfied says
111	 * "expected" rather than "in progress", takes no retry, and still refuses the
112	 * merge.
113	 */
114	const CHECK_IN_PROGRESS = /required status check.*\bis in progress\b/i;
115	
116	/** Four moves over seven seconds, which outlasts every lag seen so far. */
117	export const REF_UPDATE_ATTEMPTS = 4;
118	const REF_UPDATE_DELAYS_MS = [500, 1500, 3000] as const;
119	
120	/** How long to wait for GitHub to read its own check run as concluded. */
121	const CHECK_READ_ATTEMPTS = 4;
122	const CHECK_READ_DELAYS_MS = [500, 1000, 2000] as const;
123	
124	const wait = (ms: number): Promise<void> => new Promise((resolve) => setTimeout(resolve, ms));
125	
126	export async function performMergeWrite(
127	  github: MergeWriteGithub,
128	  intent: MergeIntent,
129	  options: { sleep?: (ms: number) => Promise<void> } = {},
130	): Promise<MergeWriteOutcome> {
131	  // Refused before anything is written. A commit whose first parent is not the
132	  // pinned base is not bindable to that base by a ref update, so composing it
133	  // would leave an object nothing can safely land — and a squash, which has one
134	  // parent and does not contain the head, is exactly that commit.
135	  if (intent.parentShas[0] !== intent.baseSha) {
136	    return {
137	      kind: "refused",
138	      detail:
139	        "the merge commit's first parent is not the base the queue pinned, so a ref update cannot bind it to that base",
140	    };
141	  }
142	
143	  const sleep = options.sleep ?? wait;
144	
145	  // Let GitHub catch up with its own check run before asking it to apply the
146	  // rule that reads it. Unreadable is not a stop: the ref update is the
147	  // authority on whether the branch may move, and the retry below covers the
148	  // window this read was trying to skip.
149	  for (let i = 0; i < CHECK_READ_ATTEMPTS; i += 1) {
150	    if (i > 0) await sleep(CHECK_READ_DELAYS_MS[Math.min(i - 1, CHECK_READ_DELAYS_MS.length - 1)] ?? 1000);
151	    const concluded = await github.requiredTurnCheckConcluded();
152	    if (concluded !== false) break;
153	  }
154	
155	  const composed = await github.createCommit({
156	    message: intent.message,
157	    tree: intent.treeOid,
158	    parents: intent.parentShas,
159	  });
160	  if (!composed.ok) {
161	    // Nothing was written to the branch, so nothing merged. Unknown rather than
162	    // a refusal, because the queue has said nothing about this attempt yet and
163	    // reconciliation reads rather than guesses.
164	    return {
165	      kind: "unknown",
166	      detail: `the merge commit could not be written (${composed.status}: ${composed.message})`,
167	    };
168	  }
169	
170	  // The same commit object every time. Composing a fresh one per retry leaves an
171	  // orphan on the repository for each attempt that GitHub refused.
172	  let landed = await github.updateRef(intent.baseRef, { sha: composed.sha, force: false });
173	  for (let i = 1; i < REF_UPDATE_ATTEMPTS; i += 1) {
174	    if (landed.ok || landed.status !== 422 || !CHECK_IN_PROGRESS.test(landed.message)) break;
175	    await sleep(REF_UPDATE_DELAYS_MS[Math.min(i - 1, REF_UPDATE_DELAYS_MS.length - 1)] ?? 1000);
176	    landed = await github.updateRef(intent.baseRef, { sha: composed.sha, force: false });
177	  }
178	  if (landed.ok) return { kind: "merged", mergeSha: landed.sha };
179	
180	  // Running out of patience with GitHub concludes nothing. The branch never
181	  // moved, and every read here would agree it did not, which is exactly the
182	  // shape of answer that would let the queue write down a refusal it has no
183	  // business being sure of. The sweep asks again later.
184	  if (landed.status === 422 && CHECK_IN_PROGRESS.test(landed.message)) {
185	    return {
186	      kind: "unknown",
187	      detail: `GitHub refused the branch move ${REF_UPDATE_ATTEMPTS} times because a required status check had not concluded (${landed.message})`,
188	    };
189	  }
190	
191	  if (NOT_A_FAST_FORWARD.test(landed.message)) {
192	    return {
193	      kind: "base-moved",
194	      detail: `the base branch is no longer ${intent.baseSha}, which is what this candidate was verified against`,
195	    };
196	  }
197	
198	  // The status code says what this call did, not what became of the pull
199	  // request. Two writers can race for one turn: one lands the merge and the
200	  // other is told 405, and reporting that as a refusal declares a merge did not
201	  // happen at the moment it just did. GitHub's reads also lag its own writes, so
202	  // one negative read is not a negative.
203	  const absence = await confirmMergeAbsence(
204	    { readPull: () => github.readPull(), baseContainsHead: () => github.baseContainsHead() },
205	    options.sleep === undefined ? {} : { sleep: options.sleep },
206	  );
207	  if (absence.kind === "merged") return { kind: "merged", mergeSha: absence.mergeSha };
208	  if (absence.kind === "not-merged") {
209	    return { kind: "not-merged", detail: `${landed.status}: ${landed.message}` };
210	  }
211	  return { kind: "unknown", detail: `${landed.status}: ${landed.message}; ${absence.reason}` };
212	}

