183	  // not carry, and an override binds an authorization this must not reissue.
184	  // Neither can be rebuilt from what survives, so neither is guessed at.
185	  if (intent.kind !== "reused" && intent.kind !== "candidate-verified") {
186	    return {
187	      status: "refused",
188	      code: "MERGE_NOT_AUTHORIZED",
189	      detail: `a ${intent.kind} merge cannot be rebuilt from its intent alone`,
190	    };
191	  }
192	  const attemptId = intent.attemptId;
193	
194	  const already = await transitionRecordFor(db, repositoryId, baseRef, attemptId);
195	  if (already !== null) {
196	    return { status: "already", attemptId, pullRequestNumber: intent.pullRequestNumber, transitionDigest: already };
197	  }
198	
199	  const { snapshot } = await readQueue(env, repositoryId, baseRef);
200	  if (snapshot.activeAttemptId === attemptId) {
201	    return {
202	      status: "refused",
203	      code: "ATTEMPT_STILL_LIVE",
204	      detail: "that attempt still holds the lane; reconcile it instead",
205	    };
206	  }
207	
208	  // The tree the branch had before this merge, from the commit itself. A
209	  // record that is not first in its epoch has to say where it started.
210	  const before = await deps.commitFacts(env, repositoryId, intent.git.baseSha);
211	  if (before === null) {
212	    return { status: "refused", code: "BASE_UNREADABLE", detail: "could not read the base this merge started from" };
213	  }
214	
215	  const head = snapshot.transitions.at(-1);
216	  const transitionSequence = (head?.transitionSequence ?? 0) + 1;
217	  const priorDigest = head?.digest ?? null;
218	
219	  // The policy the intent bound, not whatever is active now: the record says
220	  // what this merge rested on, and the policy may have changed since.
221	  const policy = await deps.activePolicy(env, repositoryId);
222	  const verified = intent.kind === "candidate-verified";
223	  const signed = await signReusedRecord({
224	    attemptId,
225	    mergeMethod: intent.mergeMethod,
226	    git: {
227	      ...intent.git,
228	      candidateSha: mergeSha,
229	      candidateTreeOid: facts.treeOid,
230	      candidateParentOids: [...facts.parentShas],
231	    },
232	    position: {
233	      queueEpoch: snapshot.queueEpoch,
234	      turnSequence: intent.turnSequence,
235	      transitionSequence,
236	      previousTransitionDigest: priorDigest as Sha256 | null,
237	    },
238	    pullRequestNumber: intent.pullRequestNumber,
239	    evidence: {
240	      workReceiptDigest: intent.evidence.workReceiptDigest,
241	      organizationId: policy?.organizationId ?? "",
242	      policyDigest: intent.policyDigest,
243	      pipelineDigest: intent.evidence.pipelineDigest,
244	      requiredSuitesDigest: intent.evidence.requiredSuitesDigest,
245	      proofCheckRunId: intent.evidence.proofCheckRunId,
246	      ...(verified ? { verifierResultDigest: intent.evidence.verifierResultDigest } : {}),
247	    },
248	    mergeIntentDigest: authorization.intentDigest,
249	    before: { baseSha: intent.git.baseSha, treeOid: before.treeOid },
250	    final: { sha: mergeSha, treeOid: facts.treeOid, parentShas: facts.parentShas },
251	    observedAt: new Date().toISOString(),
252	    signer: { sign: (bytes, typ) => deps.signRecordBytes(env, bytes, typ) },
253	  });
254	  if ("error" in signed) {
255	    return {
256	      status: "refused",
257	      code: "SIGNING_REFUSED",
258	      detail: `the queue refused to sign its own record: ${signed.error}`,
259	    };
260	  }

